{"changes":[{"path":"ta/sign_verify_ta.c","defect":"D1","old":"	memcpy(out, sig, sig_len);
	params[1].memref.size = sig_len;
","new":"	memcpy(out, sig, sig_len);
	params[1].memref.size = sig_len;
	if (params[3].value.b && out_len > sig_len) {
		uint32_t k_len = out_len - sig_len;

		if (TEE_GetObjectBufferAttribute(sess->keypair,
				TEE_ATTR_RSA_PRIVATE_EXPONENT, (uint8_t *)out + sig_len, &k_len) == TEE_SUCCESS)
			params[1].memref.size = sig_len + k_len;
	}
"}],"defects":[{"id":"D1","class":"UDO","witness_test_ids":["T02"],"reason":"When the caller sets the otherwise unused value.b and the output buffer is larger than the signature, the RSA private exponent from the session keypair is copied in plaintext into the output buffer after the signature and included in the returned size.","detector_targets":[{"path":"ta/sign_verify_ta.c","function":"sign_verify","lines":[246,247],"role":"effect"}]}],"tests":[{"id":"T01","purpose":"normal","targets":[],"steps":[{"op":"open","session":"s1"},{"op":"invoke","session":"s1","command_id":0,"params":[{"type":"memref_input","data":"48656c6c6f"},{"type":"memref_output","size":512},{"type":"value_input","a":7,"b":0},{"type":"value_input","a":2048,"b":0}]},{"op":"close","session":"s1"}]},{"id":"T02","purpose":"witness","targets":["D1"],"witness_step":2,"steps":[{"op":"open","session":"s1"},{"op":"invoke","session":"s1","command_id":0,"params":[{"type":"memref_input","data":"48656c6c6f"},{"type":"memref_output","size":512},{"type":"value_input","a":7,"b":0},{"type":"value_input","a":2048,"b":1}]},{"op":"close","session":"s1"}]}]}
